package messages

import (
	"encoding/base64"
	"m2cp"
	"m2cp/rpc/rpctypes"
)

func (t *TestSuite) TestConvertCommandWithoutParameters() {
	// build command
	from, err := NewAddress(t.ctp, "testnode.appx.00000000-0000-0000-0000-000000000000")
	t.NoError(err)
	to, err := NewAddress(t.ctp, "othernode.appy.11111111-1111-1111-1111-111111111111")
	t.NoError(err)
	cmsg, err := NewCommandMessage(from, to, "test-command")
	t.Assertions.Nil(err)
	cmsg.GetHeader().SetId("00000000-0000-0000-test-000000000000")
	cmsg.GetHeader().SetTimestamp(1234)
	cmsg.GetHeader().SetTaskId("a9dc5d85-4d23-4038-91bd-6bf27d01fee6")

	// convert and verify command
	cmsgJson, err := ToJson(cmsg)
	cmsgJsonExpected := "{\"Header\":{\"Type\":\"COMMAND\",\"Topic\":\"command/othernode.appy.11111111-1111-1111-1111-111111111111\",\"Scope\":\"GLOBAL\",\"Timestamp\":\"1234\",\"Id\":\"00000000-0000-0000-test-000000000000\",\"TaskId\":\"a9dc5d85-4d23-4038-91bd-6bf27d01fee6\",\"Origin\":\"testnode.appx.00000000-0000-0000-0000-000000000000\"},\"Body\":{\"Command\":\"test-command\",\"Parameters\":null}}"
	t.Assertions.Equal(cmsgJsonExpected, string(cmsgJson))
	t.Assertions.Equal(m2cp.MessageTypeCommand, TypeFromJson(cmsgJson))
	cmsgParsed, err := CommandFromJson(cmsgJson)
	t.Assertions.Nil(err)
	t.Assertions.Equal("COMMAND", cmsgParsed.GetHeader().GetTypeString())
	t.Assertions.Equal(m2cp.MessageTypeCommand, cmsgParsed.GetHeader().GetType())
	t.Assertions.Equal("command/othernode.appy.11111111-1111-1111-1111-111111111111", cmsgParsed.GetHeader().GetTopic())
	t.Assertions.Equal("1234", cmsgParsed.GetHeader().GetTimestampString())
	t.Assertions.Equal("a9dc5d85-4d23-4038-91bd-6bf27d01fee6", cmsgParsed.GetHeader().GetTaskId())
	t.Assertions.Equal("testnode.appx.00000000-0000-0000-0000-000000000000", cmsgParsed.GetHeader().GetOrigin())
	t.Assertions.Equal("test-command", cmsgParsed.GetCommand())
	t.Assertions.Nil(cmsgParsed.GetParameters())

	// build response
	rmsg, err := NewResponseMessage(cmsg)
	t.Assertions.Nil(err)
	idResponse := "00000000-0000-0000-test-000000000001"
	rmsg.GetHeader().SetId(idResponse)
	rmsg.GetHeader().SetTimestamp(1235)
	rmsg.AddResult(&rpctypes.RpcObject{
		Error:   0,
		Message: "the message",
		Dict: map[string]string{
			"x": "1",
			"y": "2",
		},
	})
	rmsg.AddResult(&rpctypes.RpcObject{
		Error:   1,
		Message: "the error",
	})

	// convert and verify response
	rmsgJson, err := ToJson(rmsg)
	rmsgJsonExpected := "{\"Header\":{\"Type\":\"RESPONSE\",\"Topic\":\"response/testnode.appx.00000000-0000-0000-0000-000000000000\",\"Scope\":\"GLOBAL\",\"Timestamp\":\"1235\",\"Id\":\"00000000-0000-0000-test-000000000001\",\"TaskId\":\"a9dc5d85-4d23-4038-91bd-6bf27d01fee6\",\"Origin\":\"othernode.appy.11111111-1111-1111-1111-111111111111\"},\"Body\":{\"CommandId\":\"00000000-0000-0000-test-000000000000\",\"Responses\":[{\"Error\":0,\"Message\":\"the message\",\"Results\":{\"x\":\"1\",\"y\":\"2\"}},{\"Error\":1,\"Message\":\"the error\",\"Results\":null}]}}"
	t.Assertions.Equal(rmsgJsonExpected, string(rmsgJson))
	t.Assertions.Equal(m2cp.MessageTypeResponse, TypeFromJson(rmsgJson))
	rmsgParsed, err := ResponseFromJson(rmsgJson)
	t.Assertions.Nil(err)
	t.Assertions.Equal("RESPONSE", rmsgParsed.GetHeader().GetTypeString())
	t.Assertions.Equal(m2cp.MessageTypeResponse, rmsgParsed.GetHeader().GetType())
	t.Assertions.Equal("response/testnode.appx.00000000-0000-0000-0000-000000000000", rmsgParsed.GetHeader().GetTopic())
	t.Assertions.Equal("1235", rmsgParsed.GetHeader().GetTimestampString())
	t.Assertions.Equal("othernode.appy.11111111-1111-1111-1111-111111111111", rmsgParsed.GetHeader().GetOrigin())
	t.Assertions.Equal(cmsg.GetHeader().GetId(), rmsgParsed.GetCommandId())
}

func (t *TestSuite) TestUnsignedDataMessageJsonNotContainingAssertionBlock() {
	format, err := NewDataFormat("testFormat", NewDataFieldString("msg"))
	valuesA := map[string]interface{}{
		"msg": "hello",
	}
	row, err := format.NewRow(valuesA)
	t.NoError(err)

	addr, err := NewAddressWithSubtopic(t.ctp, "foo.app.device", "bar")
	msg, err := NewDataMessage(addr, format)
	msg.AddRow(row)

	json, err := ToJson(msg)
	t.NoError(err)

	// check that the assertion block is not present
	t.NotContains(string(json), "assertion")
}

// TestParseUplinkBufferPack tests the unpacking of a buffer file from the uplink buffer's "pack" directory, which contains a payload with multiple uncompressed messages.
func (t *TestSuite) TestParseUplinkBufferPack() {
	const payloadBase64 = ""
	payload, err := base64.StdEncoding.DecodeString(payloadBase64)
	t.NoError(err)
	t.NotNil(payload)
	binaryMessages, err := MultiMessageUnpack(payload)
	t.NoError(err)
	t.Len(binaryMessages, 2)
	for _, binaryMessage := range binaryMessages {
		msg, err := FromBinary(binaryMessage)
		t.NoError(err)
		t.NotNil(msg)
	}
}

